        let aInputs = Inputs.vectors(H.self, seed: 0xF9FB_F8B4_F91A_C258)
        let maskInputs = Inputs.masks(H.Mask.self, seed: 0xF9FB_F9B4_F91A_C40B)
        for (a, mask) in everyPair(aInputs, maskInputs) {
            let port = { () -> SIMD<Int32> in
                var a = a
                var mask = mask
                return withUnsafeTemporaryAllocation(of: SIMD<Int32>.self, capacity: 1) { result in
                    unsafe portCompressedI32InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        &a,
                        where: &mask
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let reference = { () -> SIMD<Int32> in
                var a = a
                var mask = mask
                return withUnsafeTemporaryAllocation(of: SIMD<Int32>.self, capacity: 1) { result in
                    unsafe highwayCompressedI32InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        &a,
                        where: &mask
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let checkedLanes =
                HighwayReference.compressTailIsDeterministicI32() ? H.laneCount : H.trueCount(mask)
            mismatches.check(
                (0..<checkedLanes).map { port.simd[$0] },
                (0..<checkedLanes).map { reference.simd[$0] },
                "a: \(describe(a)), mask: \(describe(mask))"
            )
        }
        mismatches.record()
    }

