        let aInputs = Inputs.vectors(H.self, seed: 0x83F6_9044_FA7C_4855)
        let bitsInputs = Inputs.buffers(
            UInt8.self,
            count: (H.laneCount + 7) / 8,
            seed: 0x83F6_8F44_FA7C_46A2
        )
        for (a, bits) in everyPair(aInputs, bitsInputs) {
            let (portResult, referenceResult) = unsafe withGuardedLanes(bits) { source in
                (
                    { () -> SIMD<Int32> in
                        var a = a
                        return withUnsafeTemporaryAllocation(of: SIMD<Int32>.self, capacity: 1) {
                            result in
                            unsafe portCompressedBitsI32InVectorCode(
                                result.baseAddress.unsafelyUnwrapped,
                                &a,
                                bits: source
                            )
                            return unsafe result.baseAddress.unsafelyUnwrapped.move()
                        }
                    }(),
                    (bits + [UInt8](repeating: 0, count: 8)).withUnsafeBufferPointer { padded in
                        { () -> SIMD<Int32> in
                            var a = a
                            return withUnsafeTemporaryAllocation(of: SIMD<Int32>.self, capacity: 1)
                            { result in
                                unsafe highwayCompressedBitsI32InVectorCode(
                                    result.baseAddress.unsafelyUnwrapped,
                                    &a,
                                    bits: padded.baseAddress!
                                )
                                return unsafe result.baseAddress.unsafelyUnwrapped.move()
                            }
                        }()
                    }
                )
            }.result
            let checkedLanes = compressedLaneCount(
                bits: bits,
                lanes: H.laneCount,
                tailIsDeterministic: HighwayReference.compressTailIsDeterministicI32()
            )
            mismatches.check(
                (0..<checkedLanes).map { portResult.simd[$0] },
                (0..<checkedLanes).map { referenceResult.simd[$0] },
                "a: \(describe(a)), bits: \(describe(bits))"
            )
        }
        mismatches.record()
    }

