    @Test func storeCompressedBits() {
        let mismatches = Mismatches("portStoreCompressedBitsI32InVectorCode")
        let aInputs = Inputs.vectors(H.self, seed: 0xA040_4B57_F62A_E095)
        let bitsInputs = Inputs.buffers(
            UInt8.self,
            count: (H.laneCount + 7) / 8,
            seed: 0xA040_4A57_F62A_DEE2
        )
        let sentinel = Inputs.sentinel(Lane.self, count: H.laneCount + 4)
        for (a, bits) in everyPair(aInputs, bitsInputs) {
            var portLanes = sentinel
            var referenceLanes = sentinel
            let (portResult, referenceResult) = bits.withUnsafeBufferPointer { source in
                (
                    portLanes.withUnsafeMutableBufferPointer { destination in
                        { () -> Int in
                            var a = a
                            return unsafe portStoreCompressedBitsI32InVectorCode(
                                &a,
                                bits: source.baseAddress!,
                                to: destination.baseAddress!
                            )
                        }()
                    },
                    referenceLanes.withUnsafeMutableBufferPointer { destination in
                        (bits + [UInt8](repeating: 0, count: 8)).withUnsafeBufferPointer { padded in
                            { () -> Int in
                                var a = a
                                return unsafe highwayStoreCompressedBitsI32InVectorCode(
                                    &a,
                                    bits: padded.baseAddress!,
                                    to: destination.baseAddress!
                                )
                            }()
                        }
                    }
                )
            }
            mismatches.check(
                portLanes,
                referenceLanes,
                "a: \(describe(a)), bits: \(describe(bits))"
            )
            mismatches.check(
                portResult,
                referenceResult,
                "a: \(describe(a)), bits: \(describe(bits))"
            )
        }
        mismatches.record()
    }

