    @Test func expanded() {
        let mismatches = Mismatches("portExpandedI32InVectorCode")
        let aInputs = Inputs.vectors(H.self, seed: 0xA313_A96D_ABDF_D014)
        let maskInputs = Inputs.masks(H.Mask.self, seed: 0xA313_AA6D_ABDF_D1C7)
        for (a, mask) in everyPair(aInputs, maskInputs) {
            mismatches.check(
                { () -> SIMD<Int32> in
                    var a = a
                    var mask = mask
                    return withUnsafeTemporaryAllocation(of: SIMD<Int32>.self, capacity: 1) {
                        result in
                        unsafe portExpandedI32InVectorCode(
                            result.baseAddress.unsafelyUnwrapped,
                            &a,
                            where: &mask
                        )
                        return unsafe result.baseAddress.unsafelyUnwrapped.move()
                    }
                }(),
                { () -> SIMD<Int32> in
                    var a = a
                    var mask = mask
                    return withUnsafeTemporaryAllocation(of: SIMD<Int32>.self, capacity: 1) {
                        result in
                        unsafe highwayExpandedI32InVectorCode(
                            result.baseAddress.unsafelyUnwrapped,
                            &a,
                            where: &mask
